def transform(grid):
    """Extend eligible solid foreground bars to the right with color 1."""
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        nz = [i for i, v in enumerate(row) if v != bg]
        if not nz:
            continue
        first, last = nz[0], nz[-1]
        # The foreground occupies an uninterrupted segment; recolor its trailing background.
        if all(row[i] != bg for i in range(first, last + 1)) and last < len(row) - 1:
            for i in range(last + 1, len(row)):
                if row[i] == bg:
                    out[r][i] = 1
    return out
